fn solve(n: u8, k: u8, participations: Vec<u8>) -> u8 {
    // Determine how many participants to consider:
    let limit = n.min(participations.len() as u8) as usize;

    // Count eligible participants
    let eligible_count = participations
        .iter()
        .take(limit)
        .filter(|&&attendance| {
            // Check eligibility: 5 - attendance >= k
            5u8.saturating_sub(attendance) >= k
        })
        .count();

    // Return number of teams = eligible_count / 3 as u8
    (eligible_count / 3) as u8
}